    const M = new THREE.Matrix4(); const keys = [{ t: 0, p: [-(n - 1) * .8 - 1, .6, 3.2], l: [-(n - 1) * .8, .6, 0], f: 40 }, { t: Math.max(3, X.dur - 1), d: Math.max(3, X.dur - 1), e: 'sine', p: [(n - 1) * .9, 2.8, 6], l: [0, 1.6, 0], f: 40 }];
